<script setup>
import {computed,onBeforeUnmount,onMounted,ref,watch} from 'vue';import {echarts} from '../../config/echarts'
const props=defineProps({data:{type:Array,default:()=>[]}});const el=ref(),chart=ref();const option=computed(()=>({tooltip:{trigger:'axis'},legend:{top:0},grid:{left:45,right:18,top:38,bottom:35},xAxis:{type:'category',data:props.data.map(x=>x.time.slice(5,16).replace('T',' '))},yAxis:{type:'value'},dataZoom:props.data.length>20?[{type:'inside',start:60,end:100}]:[],series:[{name:'下单订单数',type:'bar',barMaxWidth:16,itemStyle:{color:'#557cff',borderRadius:[5,5,0,0]},data:props.data.map(x=>x.orderCount)},{name:'支付订单数',type:'line',smooth:true,symbolSize:5,lineStyle:{width:2,color:'#55ddf5'},itemStyle:{color:'#55ddf5'},data:props.data.map(x=>x.paidOrderCount)}]}));const render=()=>chart.value?.setOption(option.value,true);onMounted(()=>{chart.value=echarts.init(el.value,'warehouse');render();addEventListener('resize',chart.value.resize)});watch(option,render,{deep:true});onBeforeUnmount(()=>chart.value?.dispose())
</script><template><div ref="el" class="chart" role="img" aria-label="下单柱状与支付折线混合趋势"></div></template>
